    return (
        len(parts) >= 3
        and parts[0] == "activity-log"
        and re.fullmatch(r"\d{4}", parts[1] or "")
        and re.fullmatch(r"\d{4}-\d{2}", parts[2] or "")
        and len(parts) == 3
    )


